-- Stations for mrtguessr_stations. Generated by
-- `python scripts/seed_supabase.py --sql` from main-site/data/stations.geojson;
-- regenerate rather than edit. Run after 001. Safe to run again: it
-- updates stations by English name and never deletes one.

on conflict (name_en) do update set
  name_zh = excluded.name_zh,
  name_ta = excluded.name_ta,
  codes = excluded.codes,
  lines = excluded.lines,
  lat = excluded.lat,
  lon = excluded.lon;
